func (q *Queries) ListAllActiveConnections(ctx context.Context) ([]Connection, error) {
	rows, err := q.db.Query(ctx, listAllActiveConnections)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Connection
	for rows.Next() {
		var i Connection
		if err := rows.Scan(
			&i.ID,
			&i.TenantSlug,
			&i.Kind,
			&i.Adapter,
			&i.ExternalID,
			&i.Label,
			&i.Status,
			&i.KeyID,
			&i.Credential,
			&i.RefreshAfter,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

